<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Construction, FileClock, History, MapPinned, RotateCw, Video } from 'lucide-vue-next'
import LineChart from '@/charts/LineChart.vue'
import GaugeChart from '@/charts/GaugeChart.vue'
import TowerDeviceSelector from '@/components/tower/TowerDeviceSelector.vue'
import RealtimeMetrics from '@/components/tower/RealtimeMetrics.vue'
import AlarmCenter from '@/components/tower/AlarmCenter.vue'
import AlarmDetailDialog from '@/components/tower/AlarmDetailDialog.vue'
import VideoMonitorDialog from '@/components/tower/VideoMonitorDialog.vue'
import CameraManagementDialog from '@/components/tower/CameraManagementDialog.vue'
import HistoricalDataDialog from '@/components/tower/HistoricalDataDialog.vue'
import DeviceInfoCard from '@/components/tower/DeviceInfoCard.vue'
import DeviceArchiveDialog from '@/components/tower/DeviceArchiveDialog.vue'
import ProjectMapDialog from '@/components/tower/ProjectMapDialog.vue'
import OperationLogDialog from '@/components/tower/OperationLogDialog.vue'
import { getTowerAlarmList, getTowerDeviceDetail, getTowerDeviceList, getTowerRealtimeData } from '@/api/tower'
import type { TowerAlarm, TowerDevice, TowerDeviceDetail, TowerRealtimeData } from '@/api/towerTypes'

const devices=ref<TowerDevice[]>([]);const selectedDeviceId=ref('');const realtime=ref<TowerRealtimeData>();const alarms=ref<TowerAlarm[]>([]);const detail=ref<TowerDeviceDetail>();const loading=ref(true);const currentTime=ref('');let timer:number|undefined
const alarmDialog=ref(false);const alarmId=ref('');const videoDialog=ref(false);const cameraDialog=ref(false);const historyDialog=ref(false);const archiveDialog=ref(false);const mapDialog=ref(false);const logDialog=ref(false)
const selectedDevice=computed(()=>devices.value.find(d=>d.id===selectedDeviceId.value));const timeLabels=['-21s','-18s','-15s','-12s','-9s','-6s','-3s','现在']
const workIcons=[Construction,History,Construction,RotateCw,FileClock]
const loadDevice=async()=>{if(!selectedDeviceId.value)return;loading.value=true;try{[realtime.value,alarms.value,detail.value]=await Promise.all([getTowerRealtimeData(selectedDeviceId.value),getTowerAlarmList({deviceId:selectedDeviceId.value}),getTowerDeviceDetail(selectedDeviceId.value)])}finally{loading.value=false}}
const loadAlarms=async()=>{alarms.value=await getTowerAlarmList({deviceId:selectedDeviceId.value})}
const openAlarm=(alarm:TowerAlarm)=>{alarmId.value=alarm.id;alarmDialog.value=true}
const confirmAlarm=(alarm:TowerAlarm)=>openAlarm(alarm)
onMounted(async()=>{loading.value=true;try{devices.value=await getTowerDeviceList();selectedDeviceId.value=devices.value.find(d=>d.name.includes('西区'))?.id??devices.value[0]?.id??''}finally{if(!selectedDeviceId.value)loading.value=false}currentTime.value=new Date().toLocaleTimeString('zh-CN',{hour12:false});timer=window.setInterval(()=>{currentTime.value=new Date().toLocaleTimeString('zh-CN',{hour12:false});if(realtime.value){const next=Number(Math.max(5,realtime.value.weight+(Math.random()-.5)*1.2).toFixed(2));realtime.value={...realtime.value,weight:next,windSpeed:Number(Math.max(0,realtime.value.windSpeed+(Math.random()-.5)*.4).toFixed(1)),rotation:(realtime.value.rotation+Math.round(Math.random()*3))%360,torqueSeries:[...realtime.value.torqueSeries.slice(1),Math.round(340+Math.random()*55)],weightSeries:[...realtime.value.weightSeries.slice(1),next],metrics:realtime.value.metrics.map(m=>m.key==='weight'?{...m,value:next}:m)}}},3500)})
watch(selectedDeviceId,()=>void loadDevice())
onBeforeUnmount(()=>window.clearInterval(timer))
</script>

<template><div class="view-page tower-page"><div class="page-head"><div><p class="page-eyebrow">TOWER CRANE INTELLIGENT ANALYSIS</p><h1 class="page-title">塔吊监测分析</h1><p class="page-subtitle">实时监测、报警处置、视频复核、历史追溯一体化安全闭环</p></div><div class="page-actions"><span class="sync-status"><i class="live-dot"/>实时通讯正常 · {{ currentTime }}</span><button class="tech-button secondary" @click="logDialog=true"><FileClock :size="14"/>操作日志</button><button class="tech-button secondary" @click="mapDialog=true"><MapPinned :size="14"/>查看地图</button><button class="tech-button" @click="historyDialog=true"><History :size="14"/>历史数据</button></div></div>
  <TowerDeviceSelector v-model="selectedDeviceId" :devices="devices" :loading="loading"/>
