    <RealtimeMetrics :metrics="realtime?.metrics||[]" :loading="loading"/>
    <div class="trend-grid"><article class="tech-panel trend-card"><div class="panel-head"><h2 class="panel-title">实时力矩曲线</h2><span class="panel-meta">限值 800 m·T</span></div><div class="trend-chart"><LineChart :labels="timeLabels" :series="[{name:'力矩',data:realtime?.torqueSeries||[],color:'#3b82f6',area:true}]" unit="m·T"/></div></article><article class="tech-panel trend-card"><div class="panel-head"><h2 class="panel-title">实时吊重曲线</h2><span class="panel-meta">额定 20 T</span></div><div class="trend-chart"><LineChart :labels="timeLabels" :series="[{name:'吊重',data:realtime?.weightSeries||[],color:'#22d3ee',area:true}]" unit="T"/></div></article></div></section>
    <aside class="tower-aside"><article class="tech-panel safety-panel"><div class="panel-head"><h2 class="panel-title">设备安全评分</h2><span class="panel-meta">综合研判</span></div><div class="safety-score"><div class="score-ring"><span><strong>89</strong><small>安全</small></span></div><div class="score-items"><span>机械状态<b>92</b></span><span>作业行为<b>86</b></span><span>环境风险<b>88</b></span></div></div></article><AlarmCenter :alarms="alarms" :loading="loading" @detail="openAlarm" @confirm="confirmAlarm"/><DeviceInfoCard :detail="detail" :loading="loading" @archive="archiveDialog=true" @map="mapDialog=true"/></aside></div>
  <AlarmDetailDialog v-model="alarmDialog" :alarm-id="alarmId" @updated="loadAlarms"/><VideoMonitorDialog v-model="videoDialog" :device-id="selectedDeviceId" @manage="cameraDialog=true"/><CameraManagementDialog v-model="cameraDialog" @view="videoDialog=true"/><HistoricalDataDialog v-model="historyDialog" v-model:device-id="selectedDeviceId" :devices="devices"/><DeviceArchiveDialog v-model="archiveDialog" :device-id="selectedDeviceId"/><ProjectMapDialog v-model="mapDialog" project-id="project-02"/><OperationLogDialog v-model="logDialog"/>
</div></template>

